// ---------------------------------------------------------------------------
// The sheet
// ---------------------------------------------------------------------------

interface SheetProps {
  branding: Branding;
  footer: Footer;
  title: string;
  subtitle?: ReactNode;
  landscape?: boolean;
  /** The nursery card's brighter layout. Branding and footer are unchanged. */
  variant?: "standard" | "nursery" | "primary" | "compact";
  /** Drawn at the header's right edge, e.g. the learner's photo. */
  aside?: ReactNode;
  /** Left out for a document that flows over as many pages as it needs. */
  pageNumber?: number;
  pageCount?: number;
  children: ReactNode;
}

function Sheet({
  branding,
  footer,
  title,
  subtitle,
  landscape = false,
  variant = "standard",
  aside,
  pageNumber,
  pageCount,
  children,
}: SheetProps) {
  const contact = [branding.address, branding.phone, branding.email]
    .filter(Boolean)
    .join("  •  ");

  const className = [
    "sheet",
    landscape && "sheet-landscape",
    variant === "nursery" && "sheet-nursery",
    variant === "primary" && "sheet-nursery sheet-primary",
    variant === "compact" && "sheet-compact",
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <article
      className={className}
      style={{ "--doc-accent": branding.accentColor } as CSSProperties}
    >
      {/* --- Institution branding. Never anything else. --- */}
      <header className="doc-head">
        {branding.logoDataUrl ? (
          <img className="doc-logo" src={branding.logoDataUrl} alt="" />
        ) : (
          <div className="doc-logo-placeholder">No logo</div>
        )}

        <div className="doc-identity">
          <div className="doc-institution">{branding.institutionName}</div>
          {branding.motto && <div className="doc-motto">“{branding.motto}”</div>}
          {contact && <div className="doc-contact">{contact}</div>}
        </div>

        {aside ?? (
          // Balances the logo so the name stays optically centred.
          <div className="doc-logo-placeholder" style={{ visibility: "hidden" }} />
        )}
      </header>

      <div className="doc-title">{title}</div>
      {subtitle && <div className="doc-subtitle">{subtitle}</div>}

      <div className="doc-body">{children}</div>

      {/* --- Fixed footer, per FR-D4. --- */}
      <footer className="doc-foot">
        <span>{footer.generatedBy}</span>
        {pageNumber !== undefined && pageCount !== undefined && (
          <span>
            Page {pageNumber} of {pageCount}
          </span>
        )}
        <span>Printed {footer.printedOn}</span>
      </footer>
    </article>
  );
}

// ---------------------------------------------------------------------------
// Preview frame (screen only — hidden at print time)
// ---------------------------------------------------------------------------

export function PrintPreview({
  actions,
  children,
}: {
  actions?: ReactNode;
  children: ReactNode;
}) {
  return (
    <div className="print-root">
      <div className="print-toolbar no-print">
        <Button
          variant="primary"
          icon={<Printer size={15} />}
          onClick={() => window.print()}
        >
          Print
        </Button>
        {actions}
      </div>
      {children}
    </div>
  );
}

// ---------------------------------------------------------------------------
// FR-D1 — report card
// ---------------------------------------------------------------------------

export function ReportCardSheets({
  envelope,
}: {
  envelope: DocumentEnvelope<ReportCardBatch>;
}) {
  const { branding, footer, body } = envelope;
  // FR-C12: a learner with weekly scores gets a back page, printed right
  // after their card so double-sided printing puts it on the reverse.
  const hasBack = (card: ReportCard) => body.weeklyWeeks > 0 && card.weekly.length > 0;
  const total = body.cards.reduce((sum, card) => sum + (hasBack(card) ? 2 : 1), 0);

  let page = 0;
  return (
    <>
      {body.cards.map((card) => {
        page += 1;
        const front = page;
        const back = hasBack(card) ? ++page : null;
        const Front = body.levelKind === "nursery" ? NurseryReportSheet : ReportCardSheet;
        return (
          <Fragment key={card.studentId}>
            <Front
              branding={branding}
              footer={footer}
              batch={body}
              card={card}
              pageNumber={front}
              pageCount={total}
            />
            {back !== null && (
              <WeeklyBackSheet
                branding={branding}
                footer={footer}
                batch={body}
                card={card}
                pageNumber={back}
                pageCount={total}
              />
            )}
          </Fragment>
        );
      })}
    </>
  );
}

/** FR-C12 — the back of the report card: every week's assignment score. */
function WeeklyBackSheet({
  branding,
  footer,
  batch,
  card,
  pageNumber,
  pageCount,
}: {
  branding: Branding;
  footer: Footer;
  batch: ReportCardBatch;
  card: ReportCard;
  pageNumber: number;
  pageCount: number;
}) {
  const weeks = Array.from({ length: batch.weeklyWeeks }, (_, index) => index + 1);
  const means = card.weekly
    .map((subject) => subject.meanPercentage)
    .filter((value): value is number => value !== null);
  const overall = means.length ? means.reduce((a, b) => a + b, 0) / means.length : null;
  const done = card.weekly.reduce((sum, subject) => sum + subject.weeksDone, 0);
  const set = card.weekly.reduce((sum, subject) => sum + subject.weeksSet, 0);

  return (
    <Sheet
      branding={branding}
      footer={footer}
      variant="compact"
      landscape={weeks.length > 12}
      title="Weekly Assignments"
      subtitle={`${card.fullName}  •  ${card.className}  •  ${batch.termName} ${batch.academicYear}`}
      pageNumber={pageNumber}
      pageCount={pageCount}
    >
      <table className="wk-table">
        <thead>
          <tr>
            <th className="left">Subject</th>
            {weeks.map((week) => (
              <th key={week}>W{week}</th>
            ))}
            <th>Done</th>
            <th>Mean</th>
          </tr>
        </thead>
        <tbody>
          {card.weekly.map((subject) => (
            <tr key={subject.subject}>
              <td className="left wk-subject">{subject.subject}</td>
              {weeks.map((week, index) => {
                const score = subject.scores[index] ?? null;
                return (
                  <td key={week} className={score === null ? "wk-missed" : ""}>
                    {score === null ? (index < subject.weeksSet ? "✕" : "") : Math.round(score)}
                  </td>
                );
              })}
              <td className="wk-strong">
                {subject.weeksDone}/{subject.weeksSet}
              </td>
              <td className="wk-strong">
                {subject.meanPercentage === null ? "—" : `${Math.round(subject.meanPercentage)}%`}
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      <div className="wk-summary">
        <div className="pr-tile">
          <span>Assignments done</span>
          <strong>
            {done} of {set}
          </strong>
        </div>
        <div className="pr-tile pr-tile-accent">
          <span>Term mean</span>
          <strong>{overall === null ? "—" : `${Math.round(overall)}%`}</strong>
        </div>
        <p className="wk-note">
          Scores are percentages. ✕ marks an assignment that was set but not handed in.
        </p>
      </div>
    </Sheet>
  );
}

