function timeOf(t: string | null): string {
  return t ? new Date(t).toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" }) : "";
}

const VISIT_LABEL: Record<string, string> = {
  parent: "Parent visit",
  meeting: "Meeting",
  official: "Official visit",
  delivery: "Delivery",
  job: "Looking for work",
  other: "Other",
};

